using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static partial class TerrainSculptChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var s=new SliceState();Check(s.Valid(),"Old season rejected");s.terrainEdits=new TerrainEdits{source="island",width=32,cells=new[]{new TerrainDelta{cell=10,meters=2}}};Check(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(s)).Valid(),"Edits failed serialization");s.terrainEdits.cells[0].meters=float.NaN;Check(!s.Valid(),"Nonfinite delta accepted");s.terrainEdits.cells[0].meters=4.01f;Check(!s.Valid(),"Unbounded height accepted");s.terrainEdits.cells=new[]{new TerrainDelta{cell=10},new TerrainDelta{cell=10}};Check(!s.Valid(),"Duplicate cells accepted");s.terrainEdits.cells=new[]{new TerrainDelta{cell=1024}};Check(!s.Valid(),"Invalid grid index accepted");s.terrainEdits.cells=new TerrainDelta[TerrainEdits.Limit+1];Check(!s.Valid(),"Unbounded save accepted");Debug.Log("BWVR_SCULPT_MODEL_PASS");}
 public static void VerifyRuntime(Action<TerrainSculptor,Vector3,string> capture=null){
  var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var field=typeof(QuestSlice).GetField("state",F);var original=(SliceState)field.GetValue(slice);var sculpt=slice.GetComponentInChildren<TerrainSculptor>();var nav=slice.GetComponent<IslandNavigation>();var god=slice.GetComponentInChildren<CreatureHybrid>();var palette=slice.GetComponentInChildren<GodToolPalette>();var divine=slice.GetComponentInChildren<DivineIntervention>();var source=Resources.Load<IslandTerrainData>("FirstIsland");var sourceV=source.mesh.vertices;var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true};var unlimited=divine.tuning.unlimitedEnergy;var actor=slice.GetComponentInChildren<VillagerRoutine>();var actorPosition=actor.transform.position;
  field.SetValue(slice,test);god.Interrupt("Terrain sculpt QA");sculpt.Restore(test);
  try{
   Check(sculpt.Terrain!=source&&sculpt.Terrain.mesh!=source.mesh,"Imported terrain mutated directly");Check(GodToolPalette.ToolCount==14,"Missing sculpt buttons");divine.tuning.unlimitedEnergy=true;
   var d=sculpt.Terrain;Vector3 at=Vector3.zero;bool found=false;for(int z=d.bounds[1]+5;z<d.bounds[3]-5&&!found;z+=3)for(int x=d.bounds[0]+5;x<d.bounds[2]-5&&!found;x+=3){var p=d.Project(d.World(x,z,0));if(!d.Dry(p)||!nav.Sample(p,nav.villager,1,out _)||!nav.Sample(p,nav.creature,1,out _))continue;if(sculpt.CanSculpt(p,SpiritualTool.RaiseGround,out _)){at=p;found=true;}}
   Check(found,"No safe sculpt patch found");float initial=d.Project(at).y;capture?.Invoke(sculpt,at,"before");
   for(int i=0;i<4;i++)Check(sculpt.CanSculpt(at,SpiritualTool.RaiseGround,out _),"Preview unavailable");Check(test.terrainEdits==null&&d.Project(at).y==initial,"Preview mutated world");
   test.paused=true;Check(!sculpt.CommitImmediateForValidation(at,SpiritualTool.RaiseGround),"Paused stroke committed");test.paused=false;
   palette.ProcessSculpt(at,SpiritualTool.RaiseGround,true,true);test.Hybrid.time+=.1f;Check(!palette.ProcessSculpt(at,SpiritualTool.RaiseGround,false,true)&&test.terrainEdits==null,"Tap reshaped ground");
   palette.ProcessSculpt(at,SpiritualTool.RaiseGround,true,true);test.Hybrid.time+=1;palette.Cancel();Check(!palette.ProcessSculpt(at,SpiritualTool.RaiseGround,false,true)&&test.terrainEdits==null,"Cancel applied stroke");
   palette.ProcessSculpt(at,SpiritualTool.RaiseGround,true,true);test.Hybrid.time+=1;Check(palette.ProcessSculpt(at,SpiritualTool.RaiseGround,false,true),"Charged release failed: "+sculpt.Reason);Check(sculpt.Pending&&test.terrainEdits==null,"Requested stroke mutated ground before preparation");sculpt.CancelPending();Check(sculpt.CommitImmediateForValidation(at,SpiritualTool.RaiseGround),"Core raise failed");float raised=d.Project(at).y;Check(raised>initial+d.scale*.5f&&test.terrainEdits.strokes==1,"Raise not visible or counted");capture?.Invoke(sculpt,at,"raised");Check(!sculpt.CommitImmediateForValidation(at,SpiritualTool.RaiseGround)&&test.terrainEdits.strokes==1,"Cooldown allowed duplicate stroke");
   var collider=slice.GetComponentsInChildren<MeshCollider>().First(c=>c.sharedMesh==d.mesh);Check(collider.Raycast(new Ray(d.Project(at)+Vector3.up,Vector3.down),out var hit,2)&&Mathf.Abs(hit.point.y-raised)<d.scale*.01f,"Collision differs from surface");Check(nav.Sample(d.Project(at),nav.villager,1,out var foot)&&Mathf.Abs(nav.ProjectFoot(foot,nav.villager).y-d.Project(foot).y)<d.scale*.01f&&nav.Sample(d.Project(at),nav.creature,1,out _),"Navigation not rebuilt");
   test.Hybrid.time+=2;actor.transform.position=d.Project(at);Check(!sculpt.CommitImmediateForValidation(d.Project(at),SpiritualTool.LowerGround),"Sculpt moved occupied ground");actor.transform.position=actorPosition;
   var tree=d.placements.First(p=>p.kind=="tree");Check(!sculpt.CanSculpt(d.PlacementPoint(tree),SpiritualTool.RaiseGround,out _),"Rooted tree not protected");Check(!sculpt.CanSculpt(new Vector3(float.NaN,0,0),SpiritualTool.RaiseGround,out _),"Nonfinite point accepted");
   divine.tuning.unlimitedEnergy=false;test.Hybrid.energy=0;Check(!sculpt.CommitImmediateForValidation(d.Project(at),SpiritualTool.LowerGround),"Unaffordable stroke applied");test.Hybrid.energy=60;Check(sculpt.CommitImmediateForValidation(d.Project(at),SpiritualTool.LowerGround)&&Mathf.Abs(test.Hybrid.energy-52)<.001f,"Lower failed or wrong cost");Check(d.Project(at).y<raised,"Lower did not change height");test.Hybrid.time+=2;Check(sculpt.CommitImmediateForValidation(d.Project(at),SpiritualTool.RaiseGround),"Repeat raise failed");test.Hybrid.time+=2;float preSmooth=d.Project(at).y;Check(sculpt.CommitImmediateForValidation(d.Project(at),SpiritualTool.SmoothGround),"Smooth failed");Check(d.Project(at).y<=preSmooth+d.scale*.001f,"Smooth raised the peak");Check(d.offsets.All(v=>Mathf.Abs(v)<=TerrainEdits.MaxMeters),"Height limit exceeded");
   float savedHeight=d.Project(at).y;typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);var loaded=(SliceState)field.GetValue(slice);Check(loaded.Valid()&&loaded.terrainEdits.strokes==4&&loaded.terrainEdits.nextStrokeAt>loaded.Hybrid.time&&Mathf.Abs(d.Project(at).y-savedHeight)<d.scale*.001f,"Native save/resume lost edits");Check(loaded.Hybrid.Evidence.events.Any(e=>e.target=="island-sculpt"&&e.source==EvidenceSource.PlayerMiracle),"Player attribution missing");Check(source.offsets==null&&source.mesh.vertices.SequenceEqual(sourceV),"Source asset changed");
   palette.Select(SpiritualTool.RaiseGround);palette.Toggle();capture?.Invoke(sculpt,at,"palette");palette.Cancel();Debug.Log("BWVR_SCULPT_RUNTIME_PASS: charged release/cancel/pause; protected actors/trees; raise/lower/smooth; finite energy; collider/two nav profiles; native save/load; source isolation; last bake "+nav.LastTerrainBakeMs+"ms");
  }finally{actor.transform.position=actorPosition;divine.tuning.unlimitedEnergy=unlimited;palette.Cancel();field.SetValue(slice,original);sculpt.Restore(original);}
 }
}
}
